export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:08。門禁關上。車消失了。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪的手已經在車門把上。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "攔它。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "坐下。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "它進去了——", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "我知道。坐下。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪沒有坐下。她推開車門。一隻腳踩到地面。冷風灌進來。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "G07／12——那是悠真的碼——它正在往下走——", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "回來。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部從駕駛座伸過手。抓住她的手臂。不是用力。但是穩。像釘在原位。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳跑過去能做什麼？那裡是雙重門禁，門已經關了。妳跑到門口進不去，拍門沒人開，喊也沒人理。然後他們知道有人在看。這條路——就斷了。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "如果裡面是悠真呢？", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "如果裡面是悠真——妳跑過去能把門打開嗎？", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪停住了。一隻腳在車外。一隻腳在車裡。手還在門把上。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "回來。坐下。聽我說完。然後妳再決定要不要跑。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:09。澪慢慢把腳收回車裡。關上車門。手還在發抖。但她坐下了。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他說聽完再決定。好。聽。聽完再說。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七個理由。妳聽。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第一——沒看見人。後門開了十秒。升降板。固定架。固定帶。簾子。隔板。沒有人影。沒有擔架。沒有病人。沒有監測設備。妳看見的是設備。不是人。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第二——G07／12 可能代表設備、檢體或批次。它是一個路線牌。不是病人名牌。它可能是一箱硬碟。可能是一批檢體。可能是一組設備。代碼不能證明裡面是人。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第三——車已經進了私人門禁。雙重門禁。門關了。那裡是私人控制區。不是公共道路。我在公共道路上可以拍照。在私人門禁裡面——沒有權限。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第四——我在茨城沒有搜車權限。警視廳的權限到不了這裡。我是通報過窗口的外縣警察。不是茨城的刑警。我不能在別人的縣、別人的私人設施裡搜一輛車。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第五——茨城便衣還沒到。09:15 才到。現在 09:09。在當地警察到場之前——我連程序見證人都沒有。一個人不能在沒有屬地警察的情況下執行跨縣行動。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第六——條件式攔查門檻沒有達到。我們說過四項。未成年身影——沒看見。呼救——沒聽見。明顯醫療危險——沒看見。公共道路上的許可違規——車在門禁裡面，不在公共道路上。四項——一項都沒有成立。沒有可執行的事實。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "第七——", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了一下。看著她。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "如果裡面只有一箱硬碟——妳今天攔了——他們明天就換路線。真正的人員轉送——如果存在——會立刻改道。改到一個我們不知道的地方。改到一個沒有公共觀察點的地方。改到一個連 G07／12 都不會再出現的地方。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第七項。最重的一項。不是權限。不是程序。是——如果裡面不是人。如果裡面只有一箱硬碟。我今天攔了。搜了。什麼也沒找到。然後他們知道了。有人在查這條路。有人在看這個碼。明天——路線改了。車換了。碼換了。悠真會被送到另一個我找不到的地方。因為我今天跑了過去。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:10。車裡很安靜。窗外是關上的門禁。灰白的天。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯七個。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "七個。每一個都是程序。不是我不想攔。是——攔了，什麼都留不下。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "那你打算怎麼辦。讓它走？", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "我不是讓它走。我是在讓這條路留下來。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他說了。「我不是讓它走。我是在讓這條路留下來。」和早上那句一樣。他不是在放棄。他是在選擇。讓路活著。讓明天能查。如果今天驚動了——路就死了。悠真會消失在一條我永遠找不到的路上。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:11。澪鬆開門把。手仍然在抖。但她把雙手放回膝上。握住筆記本。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯好。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "好。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:12。車在地下。從公共位置——看不見它。看不見它在做什麼。看不見它在哪一層。看不見它停在哪裡。只能等它出來。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部拿起手機。開始查。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他查的第一項——車牌。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "剛才長焦影片裡拍到的車牌。他在手機上輸入。等公開車籍系統回覆。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:14。車籍資料回來了。登記公司名稱。他記下來。在手寫觀察表上寫——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "車牌——登記公司——搬送業務。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他查的第二項——公司公開營運項目。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "在公開企業資訊網頁上查。公司登記的營運項目。他記下來——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "檢體搬送。資料搬送。災害設備搬送。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他查的第三項——福利改裝資訊。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "在同一間公司的公開車輛改裝登記裡。他找到——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "福利車輛改裝。折疊式輪椅升降板。固定架。載人安全帶。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯公開業務是搬送。但車有載人設備。升降板。固定架。安全帶。搬箱不需要這些。業務和設備——對不上。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他查的第四項——可能的多用途解釋。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在手機上搜。同一間公司的公開招標案例。他找到——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "災害多用途車。舊改裝。人員與設備兼運。演習用途。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "多用途。災害多用途車。舊改裝。人員與設備兼運。演習用途。這是公開的解釋。合法的。合理的。夠用來擋住任何人的質疑。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "但升降板是空的。固定架是空的。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "空的。對。空的可以解釋為——今天沒有載人。今天載的是設備。空的固定架——是因為人還沒上車。或者——今天不需要。或者——這輛車本來就兼運。今天這一趟——載的是設備。公開業務寫的是搬送。車體有載人設備。兩者放在一起——多用途。合法。合理。夠用。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他說得對。多用途。合法。合理。每一項都能解釋升降板和固定架。普通解釋——不需要陰謀。不需要悠真。但普通解釋也不能排除悠真。多用途——可以載設備。也可以載人。今天載的是什麼——看不見。內部封閉艙——三層遮蔽。看得見的是設備。看不見的是裡面。普通解釋夠用。但不等於真相。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:18。日下部的手機震動。一條訊息。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "茨城便衣聯絡人。已抵達研究區外圍。目前在公共道路另一側待命。未進入園區。未表明身份。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "到了。比我預計的早了一點。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "他看到車了嗎？", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "沒有。他到的時候門已經關了。他沒看到入門。但他可以參與後續——車離開的時候，他站在公共道路上，親眼看見它駛出來。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯茨城便衣到了。沒看到入門。但可以等出門。車在地下。不知道什麼時候出來。上次——大約二十分鐘。09:30 左右。等。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:20。車仍在地下。從公共位置——什麼也看不見。門禁關著。坡道入口沉默。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部繼續在觀察表上整理。車牌。公司。公開營運項目。福利改裝資訊。多用途解釋。五項。每一項都標註來源——公開車籍系統、公開企業資訊網頁、公開車輛改裝登記、公開招標案例。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯五項。全部來自公開資料。不需要循環。不需要記憶。任何一項都能在瀏覽器裡重新查到。這是今天的證據。不是之前的記憶。日下部在做的——是把觀察變成能寫進報告的東西。車牌。公司。營運項目。改裝。多用途。五個公開來源。撐起一個結論——這輛車具備載人能力，但公開業務只登記搬送。不一致。但不違法。多用途解釋——夠用。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:25。澪翻開筆記本。在剛才的基線頁後面寫——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:03–09:08。灰白中型搬送車。雙重門禁。地下服務坡道。路線牌 G07／12、B2。外部作業艙可見載人設備。內部封閉艙不可見。未看見乘員。車籍登記為搬送業務。車體有福利改裝。多用途解釋存在。不一致。但不違法。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在下面寫——", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "G07／12 與悠真預約頁一致。B2 為目的碼。不能確認 B2 等於地下二樓。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯寫完了。今天的觀察。今天的證據。今天的界線。G07／12——一致。B2——目的碼。不能確認是地下二樓。可能是 Bay 2。可能是 Block 2。也可能是第二搬入口。或內部服務碼。不能確認。先記錄。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "09:30。門禁仍然關著。車仍在地下。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著前方。等。", background: Background.Chapter_17_Ch17_Act6_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯悠真。我不知道你在不在裡面。我看見的是設備。不是你。我看見的是代碼。不是你。我看見的是一條往下的路。不是你。但那個代碼——是你的。G07／12。你的預約頁上寫的。你的小鏡子上刻的。今天——在筑波的擋風玻璃上。第三個星期一。同一個碼。被送進了一條訪客地圖沒有標出的地下路線。我不能證明你在裡面。但我能證明——他們今天還在用你的碼。", background: Background.Chapter_17_Ch17_Act6_S0, portrait: Portrait.AsakuraMio_Determined },
];
